options.spec:
params:
  waterFilters: { select: crossfilter }
plot:
  - mark: lineY
    data: { from: samples, filterBy: $waterFilters }
    x: { sql: "date_trunc('month', t)" }
    y: { sql: "100 * avg(low)" }
    stroke: '#E4572E'
    strokeWidth: 2
    curve: monotone-x
  - mark: lineY
    data: { from: samples, filterBy: $waterFilters }
    x: { sql: "date_trunc('month', t)" }
    y: { sql: "median(temperature)" }
    stroke: '#6A9BB5'
    strokeWidth: 1.5
    strokeDasharray: 3,3
    curve: monotone-x
yDomain: [0, 30]
xLabel: null
yLabel: ↑ % under 0.2 mg/L (orange) · water °C (blue, dashed)
marginLeft: 44
marginBottom: 30
